class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        // Track maximum sum ending at current position (Kadane's Algorithm)
        int currentSum = nums[0];
        // Track global maximum subarray sum
        int maxSum = nums[0];

        for (size_t i = 1; i < nums.size(); i++) {
            // Decide whether to add current element to existing subarray or start fresh
            currentSum = max(nums[i], currentSum + nums[i]);
            // Update overall maximum
            maxSum = max(maxSum, currentSum);
        }

        return maxSum;
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        // Minimum buy price seen so far
        int minp = prices[0];
        // Maximum profit achievable
        int maxp = 0;

        for (int price : prices) {
            // Update minimum purchase price
            minp = min(minp, price);

            // Calculate profit if sold today
            int profit = price - minp;

            // Track maximum profit
            maxp = max(maxp, profit);
        }

        return maxp;
    }
};

