class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        // Base case: empty tree
        if (root == nullptr) return nullptr;

        // Recursively invert left and right subtrees
        invertTree(root->left);
        invertTree(root->right);

        // Swap left and right child pointers
        TreeNode* temp = root->left;
        root->left = root->right;
        root->right = temp;

        return root;
    }
};

class MinStack {
public:
    // Stack stores pairs: {element_value, current_minimum}
    stack<pair<int, int>> s;

    MinStack() {

    }

    // Push element onto stack and record updated minimum
    void push(int value) {
        if (s.empty()) {
            s.push({value, value});
        } else {
            int minVal = min(value, s.top().second);
            s.push({value, minVal});
        }
    }

    // Remove top element from stack
    void pop() {
        s.pop();
    }

    // Retrieve top element value
    int top() {
        return s.top().first;        
    }

    // Retrieve minimum element in stack in O(1)
    int getMin() {
        return s.top().second;
    }
};

