class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        // Map sorted canonical string to list of original anagram strings
        unordered_map<string, vector<string>> mp;

        for (string s : strs) {
            string key = s;
            // Sort characters to create unique key for anagrams
            sort(key.begin(), key.end());
            mp[key].push_back(s);
        }

        vector<vector<string>> result;

        // Collect all grouped anagram lists
        for (auto& pair : mp) {
            result.push_back(pair.second);
        }

        return result;
    }
};

class Solution {
public:
    bool isSameTree(TreeNode* p, TreeNode* q) {
        // Both nodes are null -> identical
        if (p == nullptr && q == nullptr) {
            return true;
        }

        // One node is null while other is not -> not identical
        if (p == nullptr || q == nullptr) {
            return false;
        }

        // Node values differ -> not identical
        if (p->val != q->val) {
            return false;
        }

        // Check both left and right subtrees recursively
        return isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
    }
};

class Solution {
public:
    ListNode* removeElements(ListNode* head, int val) {
        // Dummy node simplifies node deletion at head
        ListNode dummy(0);
        dummy.next = head;

        ListNode* curr = &dummy;

        // Traverse linked list and skip nodes matching val
        while (curr->next != nullptr) {
            if (curr->next->val == val) {
                ListNode* toDelete = curr->next;
                curr->next = curr->next->next;
                delete toDelete; // Memory cleanup
            } else {
                curr = curr->next;
            }
        }

        return dummy.next;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        // Double loop to check all pairs for target sum
        for (size_t i = 0; i < nums.size(); i++) {
            for (size_t j = i + 1; j < nums.size(); j++) {
                if (nums[i] + nums[j] == target) {
                    return {static_cast<int>(i), static_cast<int>(j)};
                }
            }
        }
        return {};
    }
};
